CREATE DATABASE IF NOT EXISTS hospital_management CHARACTER SET utf8mb4;
USE hospital_management;
CREATE TABLE IF NOT EXISTS roles(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,role_id INT NOT NULL,is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS patients(id INT AUTO_INCREMENT PRIMARY KEY,patient_code VARCHAR(24) UNIQUE NOT NULL,full_name VARCHAR(120) NOT NULL,dob DATE,gender VARCHAR(20),blood_group VARCHAR(5),phone VARCHAR(20),email VARCHAR(120),address TEXT,emergency_contact VARCHAR(120),medical_history TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,created_by INT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(full_name));
CREATE TABLE IF NOT EXISTS doctors(id INT AUTO_INCREMENT PRIMARY KEY,doctor_code VARCHAR(24) UNIQUE NOT NULL,full_name VARCHAR(120) NOT NULL,department_id INT,specialization VARCHAR(100),qualification VARCHAR(120),phone VARCHAR(20),consultation_fee DECIMAL(10,2) DEFAULT 0,schedule_text VARCHAR(255),is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS appointments(id INT AUTO_INCREMENT PRIMARY KEY,appointment_code VARCHAR(24) UNIQUE NOT NULL,patient_id INT NOT NULL,doctor_id INT NOT NULL,appointment_at DATETIME NOT NULL,reason VARCHAR(255),status ENUM('Scheduled','Confirmed','Completed','Cancelled','No-show') DEFAULT 'Scheduled',created_by INT,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(doctor_id,appointment_at));
CREATE TABLE IF NOT EXISTS wards(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL,ward_type VARCHAR(50));
CREATE TABLE IF NOT EXISTS beds(id INT AUTO_INCREMENT PRIMARY KEY,bed_code VARCHAR(20) UNIQUE NOT NULL,ward_id INT NOT NULL,is_available BOOLEAN DEFAULT TRUE,FOREIGN KEY(ward_id) REFERENCES wards(id));
CREATE TABLE IF NOT EXISTS admissions(id INT AUTO_INCREMENT PRIMARY KEY,admission_code VARCHAR(24) UNIQUE NOT NULL,patient_id INT NOT NULL,bed_id INT NOT NULL,admitted_at DATETIME NOT NULL,discharged_at DATETIME,diagnosis TEXT,status ENUM('Admitted','Discharged') DEFAULT 'Admitted',FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(bed_id) REFERENCES beds(id));
CREATE TABLE IF NOT EXISTS prescriptions(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,diagnosis TEXT,notes TEXT,prescribed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id));
CREATE TABLE IF NOT EXISTS prescription_items(id INT AUTO_INCREMENT PRIMARY KEY,prescription_id INT NOT NULL,medicine_name VARCHAR(120) NOT NULL,dosage VARCHAR(80),frequency VARCHAR(80),duration VARCHAR(80),instructions TEXT,FOREIGN KEY(prescription_id) REFERENCES prescriptions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS medical_records(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT,diagnosis TEXT,treatment TEXT,allergies TEXT,remarks TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS medicines(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,manufacturer VARCHAR(120),stock_qty INT DEFAULT 0,unit_price DECIMAL(10,2) DEFAULT 0,expiry_date DATE,reorder_level INT DEFAULT 10);
CREATE TABLE IF NOT EXISTS inventory_transactions(id INT AUTO_INCREMENT PRIMARY KEY,medicine_id INT NOT NULL,change_qty INT NOT NULL,transaction_type ENUM('IN','OUT') NOT NULL,note VARCHAR(255),created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(medicine_id) REFERENCES medicines(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS invoices(id INT AUTO_INCREMENT PRIMARY KEY,invoice_code VARCHAR(24) UNIQUE NOT NULL,patient_id INT NOT NULL,consultation_fee DECIMAL(10,2) DEFAULT 0,room_charges DECIMAL(10,2) DEFAULT 0,medicine_charges DECIMAL(10,2) DEFAULT 0,lab_charges DECIMAL(10,2) DEFAULT 0,other_charges DECIMAL(10,2) DEFAULT 0,discount DECIMAL(10,2) DEFAULT 0,total_amount DECIMAL(10,2) NOT NULL,amount_paid DECIMAL(10,2) DEFAULT 0,status ENUM('Pending','Partially Paid','Paid') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,created_by INT,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS payments(id INT AUTO_INCREMENT PRIMARY KEY,payment_code VARCHAR(24) UNIQUE NOT NULL,invoice_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL,method ENUM('Cash','UPI','Card','Bank Transfer') NOT NULL,reference_no VARCHAR(100),paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,received_by INT,FOREIGN KEY(invoice_id) REFERENCES invoices(id),FOREIGN KEY(received_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,username VARCHAR(60),user_role VARCHAR(30),action VARCHAR(100) NOT NULL,module VARCHAR(60) NOT NULL,record_id VARCHAR(40),description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(created_at));
